import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React from 'react';
import { appColors } from '../../../../theme/appColors';
import DeleteIcon from '@mui/icons-material/Delete';
import DiamondIcon from '@mui/icons-material/Diamond';
import { useAppDispatch, useAppSelector } from '../../../../store/hooks';
import { clearBasket, removeBasket } from '../../store/BasketSlice';
import { useSavePurchaseJewelleryMutation, useGetUserQuery } from '../../../posApi';
import { useNotifier } from '../../../../core/Notifier';
import usePurchase from '../../usePurchase';
import BackdropLoading from '../../../../components/BackdropLoading';
import ConfirmationModel from '../../../../components/ModelPopup/ConfirmationModel';
import { Receipt } from '../Receipt';
import { useReactToPrint } from 'react-to-print';
import { IPurchaseReceipt } from '../../../../core/Interface/purchase.interface';
import { IUserInfo } from '../../../../core/Interface/user.interface';
import { calculateFontSize } from '../../../../core/utils';
import { selectSupplier } from '../../store/BasketSelector';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>{text}</Typography>
);

const JewelLastSection = () => {
  const dispatch = useAppDispatch();
  const { showErrorMessage, showMessage } = useNotifier();
  const { purchaseDetails } = usePurchase();
  const [savePurchase, { isLoading }] = useSavePurchaseJewelleryMutation();
  const [openDeleteConfirmation, setOpenDeleteConfirmation] = React.useState(false);

  const supplier = useAppSelector(selectSupplier);
  const basketItems = useAppSelector((state) => state.purchaseJewelBasket.items);

  const hasItems = basketItems.length > 0;
  const hasSupplier = Boolean(supplier.mobile && supplier.mobile.trim() && supplier.supplierName && supplier.supplierName.trim());
  const canFinish = hasItems && hasSupplier;

  const { data: companyData } = useGetUserQuery();

  const printPaperSizeInPixel = React.useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.branch.printPaperSizeInPixel) {
        return Number(userData.branch.printPaperSizeInPixel);
      }
    }
    return 280;
  }, [companyData]);

  const [receiptData, setReceiptData] = React.useState<IPurchaseReceipt | null>(null);
  const componentRef = React.useRef<HTMLDivElement | null>(null);

  const handlePrint = useReactToPrint({
    content: () => componentRef.current,
  });

  const handleFinish = async () => {
    if (!canFinish) return;
    try {
      const res = await savePurchase(purchaseDetails).unwrap();
      if (!res.status) {
        showErrorMessage(res.message);
        return;
      }
      showMessage(res.message);
      setReceiptData(res.data as IPurchaseReceipt);
      dispatch(removeBasket());
      setTimeout(() => handlePrint(), 300);
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleDeleteAll = () => {
    dispatch(clearBasket());
    setOpenDeleteConfirmation(false);
  };

  return (
    <Box>
      <Grid container spacing={1}>
        {/* Delete */}
        <Grid item key="jewel_last_delete" md={1.5} sm={4} xs={4}>
          <Item
            onClick={hasItems ? () => setOpenDeleteConfirmation(true) : undefined}
            sx={{
              background: 'linear-gradient(135deg, #fee2e2 0%, #fecaca 100%)',
              opacity: hasItems ? 1 : 0.35,
              cursor: hasItems ? 'pointer' : 'default',
            }}
          >
            <Stack alignItems="center" direction="column">
              <DeleteIcon sx={{ fontSize: 26, color: '#DC2626' }} />
              {btnLabel('Delete')}
            </Stack>
          </Item>
        </Grid>

        {/* Filler tiles */}
        {[1, 2, 3, 4, 5].map((k) => (
          <Grid item key={'jewel_last_filler_' + k} md={1.5} sm={4} xs={4}>
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
          </Grid>
        ))}

        {/* FINISH */}
        <Grid item key="jewel_last_finish" md={3} sm={4} xs={4}>
          <Item
            onClick={canFinish ? handleFinish : undefined}
            sx={{
              background: canFinish
                ? 'linear-gradient(135deg, #7c3aed 0%, #4f46e5 100%)'
                : 'rgba(148,163,184,0.25)',
              opacity: canFinish ? 1 : 0.35,
              cursor: canFinish ? 'pointer' : 'default',
              boxShadow: canFinish ? '0 4px 14px rgba(124,58,237,0.35)' : 'none',
            }}
          >
            <Stack alignItems="center" direction="row" spacing={1}>
              <DiamondIcon sx={{ fontSize: 32, color: appColors.white }} />
              <Typography sx={{ fontWeight: 900, fontSize: 20, color: appColors.white, letterSpacing: '0.5px' }}>
                FINISH
              </Typography>
            </Stack>
          </Item>
        </Grid>
      </Grid>

      {openDeleteConfirmation && (
        <ConfirmationModel
          content="This will remove all items from the jewellery basket."
          handleClose={() => setOpenDeleteConfirmation(false)}
          onConfirm={() => handleDeleteAll()}
          open={openDeleteConfirmation}
          title="Delete All Items?"
        />
      )}

      {receiptData && (
        <Box sx={{ display: 'none' }}>
          <Receipt
            fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
            fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
            key={receiptData.receiptNo}
            label={calculateFontSize(printPaperSizeInPixel).label}
            purchaseRes={receiptData}
            ref={componentRef}
            width={printPaperSizeInPixel}
          />
        </Box>
      )}

      <BackdropLoading isLoading={isLoading} />
    </Box>
  );
};

export default React.memo(JewelLastSection);
