import AnimatedPage from '../../layouts/AnimatedPage';
import { Box } from '@mui/material';
import React, { useEffect } from 'react';
import PurchaseJewelleryLeft from './components/PurchaseJewelleryLeft/Index';
import PurchaseJewelleryRight from './components/PurchaseJewelleryRight/Index';

const PurchaseJewellery = () => {
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  return (
    <AnimatedPage>
      <Box sx={{ height: '100vh', overflow: 'hidden' }}>
        <PurchaseJewelleryLeft />
        <PurchaseJewelleryRight />
      </Box>
    </AnimatedPage>
  );
};

export default PurchaseJewellery;
